/* =========================================================
   CONSTANTS & STATE
========================================================= */
const HERO_PHRASES = [
  "Building Fast Websites!",
  "Crafting Modern UIs!",
  "Responsive Web Experiences!",
];

const TYPE_SPEED = 120;
const DELETE_SPEED = 60;
const PAUSE_TIME = 1800;
const OBSERVER_MARGIN = "-45% 0px -45% 0px";

let phraseIndex = 0;
let charIndex = 0;
let isDeleting = false;
let typingTimer = null;
let sectionObserver = null;

/* =========================================================
   THEME TOGGLE (DARK / LIGHT MODE)
========================================================= */
function applySavedTheme() {
  if (localStorage.getItem("lightMode") === "true") {
    document.body.classList.add("light-mode");
  }
}

function initThemeToggle() {
  const themeInput = document.getElementById("theme-toggle");
  if (!themeInput) return;

  themeInput.checked = document.body.classList.contains("light-mode");

  themeInput.addEventListener("change", () => {
    document.body.classList.toggle("light-mode");
    localStorage.setItem(
      "lightMode",
      document.body.classList.contains("light-mode")
    );
  });
}

/* =========================================================
   MOBILE NAVIGATION DRAWER
========================================================= */
function initMobileMenu() {
  const menuToggle = document.getElementById("menu-toggle");
  const navMenu = document.getElementById("nav-menu");
  if (!menuToggle || !navMenu) return;

  const navLinks = navMenu.querySelectorAll("a");

  const closeMenu = () => {
    navMenu.classList.remove("nav-active");
    menuToggle.classList.replace("fa-xmark", "fa-bars");
    menuToggle.setAttribute("aria-expanded", "false");
  };

  const toggleMenu = () => {
    const isOpen = navMenu.classList.toggle("nav-active");
    menuToggle.classList.toggle("fa-bars", !isOpen);
    menuToggle.classList.toggle("fa-xmark", isOpen);
    menuToggle.setAttribute("aria-expanded", String(isOpen));
  };

  menuToggle.addEventListener("click", toggleMenu);

  menuToggle.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      toggleMenu();
    }
  });

  navLinks.forEach((link) => link.addEventListener("click", closeMenu));

  document.addEventListener("click", (e) => {
    if (
      navMenu.classList.contains("nav-active") &&
      !navMenu.contains(e.target) &&
      !menuToggle.contains(e.target)
    ) {
      closeMenu();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && navMenu.classList.contains("nav-active")) {
      closeMenu();
    }
  });
}

/* =========================================================
   ACTIVE NAVIGATION SCROLL SPY
========================================================= */
function initScrollSpy() {
  const sections = document.querySelectorAll("section[id]");
  const navLinks = document.querySelectorAll(".nav-link");
  if (!sections.length || !navLinks.length) return;

  sectionObserver = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;

        const targetHref = `#${entry.target.id}`;
        navLinks.forEach((link) => {
          const isMatch = link.getAttribute("href") === targetHref;
          link.classList.toggle("active-link", isMatch);

          if (isMatch) {
            link.setAttribute("aria-current", "page");
          } else {
            link.removeAttribute("aria-current");
          }
        });
      });
    },
    { rootMargin: OBSERVER_MARGIN, threshold: 0 }
  );

  sections.forEach((section) => sectionObserver.observe(section));
}

/* =========================================================
   HERO TYPING ANIMATION
========================================================= */
function scheduleTyping(delay) {
  clearTimeout(typingTimer);
  typingTimer = setTimeout(runTypingEffect, delay);
}

function runTypingEffect() {
  const textTarget = document.querySelector(".typing-text");
  if (!textTarget || !document.body.contains(textTarget)) {
    clearTimeout(typingTimer);
    return;
  }

  const currentPhrase = HERO_PHRASES[phraseIndex];
  charIndex += isDeleting ? -1 : 1;
  textTarget.textContent = currentPhrase.slice(0, charIndex);

  if (!isDeleting && charIndex === currentPhrase.length) {
    isDeleting = true;
    scheduleTyping(PAUSE_TIME);
    return;
  }

  if (isDeleting && charIndex === 0) {
    isDeleting = false;
    phraseIndex = (phraseIndex + 1) % HERO_PHRASES.length;
  }

  scheduleTyping(isDeleting ? DELETE_SPEED : TYPE_SPEED);
}

/* =========================================================
   PROJECT CARD TABS
========================================================= */
function initProjectTabs() {
  document.addEventListener("click", (e) => {
    const tabBtn = e.target.closest(".project-tab-btn");
    if (!tabBtn) return;

    e.preventDefault();
    const card = tabBtn.closest(".project-card");
    if (!card) return;

    const targetTab = tabBtn.getAttribute("data-tab");

    card.querySelectorAll(".project-tab-btn").forEach((btn) => {
      btn.classList.remove("active");
      btn.setAttribute("aria-selected", "false");
    });

    card.querySelectorAll(".project-tab-pane").forEach((pane) => {
      pane.classList.remove("active");
    });

    tabBtn.classList.add("active");
    tabBtn.setAttribute("aria-selected", "true");

    const activePane = card.querySelector(`.project-tab-pane[data-pane="${targetTab}"]`);
    if (activePane) {
      activePane.classList.add("active");
    }
  });
}

/* =========================================================
   PROJECTS MOBILE CAROUSEL
========================================================= */
function initProjectCarousel() {
  const track = document.getElementById("projects-track");
  const prevBtn = document.getElementById("slide-prev");
  const nextBtn = document.getElementById("slide-next");
  const dots = document.querySelectorAll(".carousel-dot");

  if (!track || !prevBtn || !nextBtn || !dots.length) return;

  const cards = track.querySelectorAll(".project-card");
  if (!cards.length) return;

  let activeIndex = 0;

  const updateDots = (index) => {
    dots.forEach((dot, i) => {
      dot.classList.toggle("active", i === index);
    });
  };

  const goToSlide = (index) => {
    activeIndex = (index + cards.length) % cards.length;
    const baseOffset = cards[0].offsetLeft;
    const targetLeft = cards[activeIndex].offsetLeft - baseOffset;

    track.scrollTo({
      left: targetLeft,
      behavior: "smooth",
    });

    updateDots(activeIndex);
  };

  nextBtn.addEventListener("click", () => goToSlide(activeIndex + 1));
  prevBtn.addEventListener("click", () => goToSlide(activeIndex - 1));

  dots.forEach((dot, index) => {
    dot.addEventListener("click", () => goToSlide(index));
  });

  let scrollTimer;
  track.addEventListener(
    "scroll",
    () => {
      clearTimeout(scrollTimer);
      scrollTimer = setTimeout(() => {
        const step =
          cards.length > 1
            ? cards[1].offsetLeft - cards[0].offsetLeft
            : track.clientWidth;

        if (!step) return;

        const newIndex = Math.round(track.scrollLeft / step);
        if (newIndex >= 0 && newIndex < cards.length) {
          activeIndex = newIndex;
          updateDots(activeIndex);
        }
      }, 60);
    },
    { passive: true }
  );
}

/* =========================================================
   SCROLLBAR EDGE ARROW VISIBILITY
========================================================= */
function initScrollbarArrows() {
  const root = document.documentElement;
  let lastAtTop = null;
  let lastAtBottom = null;

  const syncArrowIcons = () => {
    const isAtTop = root.classList.contains("at-top");
    const isAtBottom = root.classList.contains("at-bottom");

    root.style.setProperty(
      "--current-arrow-up",
      isAtTop ? "none" : "var(--scrollbar-arrow-up)"
    );
    root.style.setProperty(
      "--current-arrow-down",
      isAtBottom ? "none" : "var(--scrollbar-arrow-down)"
    );
  };

  const updateArrowVisibility = () => {
    const scrollTop = Math.ceil(window.scrollY || root.scrollTop || 0);
    const maxScroll = Math.floor(root.scrollHeight - root.clientHeight);

    const isAtTop = scrollTop <= 4;
    const isAtBottom = maxScroll <= 4 || scrollTop >= maxScroll - 4;

    if (isAtTop === lastAtTop && isAtBottom === lastAtBottom) return;

    lastAtTop = isAtTop;
    lastAtBottom = isAtBottom;

    root.classList.toggle("at-top", isAtTop);
    root.classList.toggle("at-bottom", isAtBottom);
    syncArrowIcons();
  };

  updateArrowVisibility();
  window.addEventListener("scroll", updateArrowVisibility, { passive: true });
  window.addEventListener("resize", updateArrowVisibility, { passive: true });
  window.addEventListener("load", updateArrowVisibility);

  const themeInput = document.getElementById("theme-toggle");
  if (themeInput) {
    themeInput.addEventListener("change", syncArrowIcons);
  }
}

/* =========================================================
   FOOTER YEAR & PRELOADER
========================================================= */
function setFooterYear() {
  const yearEl = document.getElementById("current-year");
  if (yearEl) {
    yearEl.textContent = new Date().getFullYear();
  }
}

function hidePreloader() {
  const preloader = document.getElementById("preloader");
  if (preloader && !preloader.classList.contains("hide")) {
    preloader.classList.add("hide");
  }
}

/* =========================================================
   INITIALIZATION & LIFECYCLE
========================================================= */
applySavedTheme();

document.addEventListener("DOMContentLoaded", () => {
  if (typeof AOS !== "undefined") {
    AOS.init({
      once: false,
      duration: 500,
    });
  }

  initThemeToggle();
  initMobileMenu();
  initScrollSpy();
  initProjectTabs();
  initProjectCarousel();
  initScrollbarArrows();
  setFooterYear();
  scheduleTyping(TYPE_SPEED);
});

window.addEventListener("load", () => {
  setTimeout(hidePreloader, 500);

  if (typeof AOS !== "undefined") {
    setTimeout(() => AOS.refresh(), 600);
  }
});

setTimeout(hidePreloader, 3000);

window.addEventListener("beforeunload", () => {
  clearTimeout(typingTimer);
  if (sectionObserver) {
    sectionObserver.disconnect();
  }
});

